--
-- ══════════════════════════════════════════════════════════════════════
-- PRODUCTION-SCHEMA-SNAPSHOT-RECOVERY · CostPro (Supabase wthkddeleylijmonclxg)
-- ══════════════════════════════════════════════════════════════════════
-- Fecha de extracción : 2026-08-28 (UTC) · Autorización: dueño — Opción A
-- Método              : consultas SELECT-only sobre pg_catalog vía Management API
--                       (pg_dump directo imposible: sin contraseña de BD; host directo
--                       IPv6-only inaccesible desde sandbox; ver manifiesto 71)
-- Alcance             : esquema public únicamente (DDL: tablas, columnas, tipos,
--                       PK/FK/CHECK/UNIQUE, índices, enums, funciones, triggers,
--                       secuencias, vistas/matviews, RLS, grants, default ACLs,
--                       event triggers, publicaciones)
-- DATOS DE NEGOCIO    : NINGUNO — este archivo no contiene filas de ninguna tabla
-- ADVERTENCIA         : NO es la «verdad histórica del harness perdido». Es una
--                       NUEVA evidencia de recuperación (cadena: harness=LOST,
--                       baseline=LOST, este snapshot=RECOVERED). No presentarlo
--                       como original bajo ningún concepto.
-- Desviación de origen: prod=PostgreSQL 17.6.1.063/aarch64 · lab=17.11/x86_64
--                       (DEV-MINOR-VERSION-DEVIATION, declarada)
-- Exclusiones declaradas: extensiones de plataforma pg_stat_statements (requiere
--                       shared_preload) y supabase_vault (específica Supabase);
--                       esquemas auth/storage/supabase_* (cubiertos por SHIMS lab)
-- ══════════════════════════════════════════════════════════════════════
--
SET statement_timeout = 0;
SET client_encoding = 'UTF8';
SET check_function_bodies = false;
SET client_min_messages = warning;
SET row_security = off;

CREATE EXTENSION IF NOT EXISTS plpgsql;

CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;

CREATE TYPE public.cash_movement_type_enum AS ENUM ('in', 'out');

CREATE TYPE public.cash_session_status_enum AS ENUM ('open', 'closed');

CREATE TYPE public.discount_type_enum AS ENUM ('fixed', 'percentage');

CREATE TYPE public.inventory_adjustment_reason AS ENUM ('STOCKTAKE_SHRINKAGE', 'STOCKTAKE_SURPLUS', 'DAMAGED_GOODS', 'OTHER');

CREATE TYPE public.membership_status AS ENUM ('active', 'revoked');

CREATE TYPE public.movement_type AS ENUM ('sale', 'purchase', 'adjustment', 'return', 'initial', 'transfer', 'void', 'transfer_in', 'transfer_out', 'sale_void', 'production_out', 'production_in', 'sale_reverse', 'purchase_reverse', 'production_reverse', 'issue_slip_out', 'issue_slip_reverse');

CREATE TYPE public.payment_method_enum AS ENUM ('cash', 'card', 'transfer', 'wallet', 'other', 'mixed', 'zelle');

CREATE TYPE public.plan_t AS ENUM ('free', 'pro', 'enterprise');

CREATE TYPE public.product_status AS ENUM ('DRAFT', 'ACTIVE', 'DEPRECATED');

CREATE TYPE public.purchase_status_enum AS ENUM ('draft', 'sent', 'partial', 'received', 'cancelled');

CREATE TYPE public.transaction_status AS ENUM ('pending', 'completed', 'failed', 'compensated', 'cancelled', 'refunded', 'voided', 'reversed');

CREATE TYPE public.transfer_status AS ENUM ('PENDIENTE', 'CONFIRMADA', 'CANCELADA', 'REVERSADA');

CREATE TYPE public.user_role AS ENUM ('admin', 'superadmin', 'manager', 'clerk', 'warehouse', 'encargado', 'usuario', 'costo', 'tenant_admin');

CREATE TYPE public.variant_decomposition AS (variant_id uuid, quantity numeric(12,4));

CREATE TYPE public.adjustment_item AS (product_id uuid, expected_quantity numeric(12,4), counted_quantity numeric(12,4), decomposition variant_decomposition[]);

CREATE SEQUENCE public.audit_events_seq_id_seq AS bigint START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE;

CREATE SEQUENCE public.devolutions_number_seq AS bigint START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 100 NO CYCLE;

CREATE SEQUENCE public.internal_barcode_seq AS bigint START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE;

CREATE SEQUENCE public.production_order_number_seq AS bigint START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE;

CREATE SEQUENCE public.service_number_seq AS bigint START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE;

