  payment_method text NOT NULL,
  currency text DEFAULT 'CUP'::text NOT NULL,
  exchange_rate numeric DEFAULT 1.0 NOT NULL,
  amount_cup numeric GENERATED ALWAYS AS (
CASE
    WHEN (currency = 'CUP'::text) THEN amount
    ELSE (amount * exchange_rate)
END) STORED NOT NULL,
  payment_date timestamp with time zone DEFAULT now() NOT NULL,
  reference text,
  notes text,
  paid_by uuid,
