  difference numeric(12,4) GENERATED ALWAYS AS ((COALESCE(counted_quantity, (0)::numeric) - expected_quantity)) STORED,
  unit_cost numeric(12,4) DEFAULT 0 NOT NULL,
  value_discrepancy numeric(15,2) GENERATED ALWAYS AS (((COALESCE(counted_quantity, (0)::numeric) - expected_quantity) * unit_cost)) STORED,
  counted_at timestamp with time zone,
  notes text,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);

