CREATE VIEW public.v_document_state_summary WITH (security_invoker = true) AS
 SELECT 'transactions'::text AS document_type,
    transactions.store_id,
    transactions.status::text AS status,
    count(*)::integer AS count
   FROM transactions
  GROUP BY transactions.store_id, transactions.status
UNION ALL
 SELECT 'receipts'::text AS document_type,
    receipts.store_id,
    receipts.status,
    count(*)::integer AS count
   FROM receipts
  GROUP BY receipts.store_id, receipts.status
UNION ALL
 SELECT 'transfers'::text AS document_type,
    transfers.origin_store_id AS store_id,
    transfers.status::text AS status,
    count(*)::integer AS count
   FROM transfers
  GROUP BY transfers.origin_store_id, transfers.status
UNION ALL
 SELECT 'devolutions'::text AS document_type,
    devolutions.store_id,
    devolutions.status,
    count(*)::integer AS count
   FROM devolutions
  GROUP BY devolutions.store_id, devolutions.status
UNION ALL
 SELECT 'inventory_adjustments'::text AS document_type,
    inventory_adjustments.store_id,
    inventory_adjustments.status,
    count(*)::integer AS count
   FROM inventory_adjustments
  GROUP BY inventory_adjustments.store_id, inventory_adjustments.status
UNION ALL
 SELECT 'production_orders'::text AS document_type,
    production_orders.store_id,
    production_orders.status,
    count(*)::integer AS count
   FROM production_orders
  GROUP BY production_orders.store_id, production_orders.status;

CREATE VIEW public.v_global_operation_dates WITH (security_invoker = true) AS
 SELECT 'sale'::text AS doc_type,
    transactions.id AS doc_id,
    transactions.store_id,
    COALESCE(transactions.cancelled_at, transactions.created_at) AS operation_date
   FROM transactions
  WHERE transactions.status = ANY (ARRAY['completed'::transaction_status, 'voided'::transaction_status])
UNION ALL
 SELECT 'transfer'::text AS doc_type,
    transfers.id AS doc_id,
    transfers.origin_store_id AS store_id,
    transfers.created_at AS operation_date
   FROM transfers
  WHERE transfers.status = ANY (ARRAY['PENDIENTE'::transfer_status, 'CONFIRMADA'::transfer_status])
UNION ALL
 SELECT 'inventory_adjustment'::text AS doc_type,
    inventory_adjustments.id AS doc_id,
    inventory_adjustments.store_id,
    inventory_adjustments.created_at AS operation_date
   FROM inventory_adjustments
  WHERE inventory_adjustments.status IS NOT NULL
UNION ALL
 SELECT 'purchase_order'::text AS doc_type,
    purchase_orders.id AS doc_id,
    purchase_orders.store_id,
    COALESCE(purchase_orders.received_at, purchase_orders.created_at) AS operation_date
   FROM purchase_orders
  WHERE purchase_orders.status IS NOT NULL
UNION ALL
 SELECT 'receipt'::text AS doc_type,
    receipts.id AS doc_id,
    receipts.store_id,
    COALESCE(receipts.reception_date::timestamp with time zone, receipts.created_at) AS operation_date
   FROM receipts
  WHERE receipts.status IS NOT NULL
UNION ALL
 SELECT 'cash_closure'::text AS doc_type,
    cash_closures.id AS doc_id,
    cash_closures.store_id,
    COALESCE(cash_closures.closed_at, cash_closures.created_at) AS operation_date
   FROM cash_closures
UNION ALL
 SELECT 'cash_movement'::text AS doc_type,
    cash_movements.id AS doc_id,
    cash_movements.store_id,
    cash_movements.created_at AS operation_date
   FROM cash_movements
UNION ALL
 SELECT 'cash_session'::text AS doc_type,
    cash_sessions.id AS doc_id,
    cash_sessions.store_id,
    COALESCE(cash_sessions.opening_at, cash_sessions.created_at) AS operation_date
   FROM cash_sessions
UNION ALL
 SELECT 'stock_movement'::text AS doc_type,
    stock_movements.id AS doc_id,
    stock_movements.store_id,
    stock_movements.created_at AS operation_date
   FROM stock_movements;

CREATE VIEW public.v_physical_count_summary WITH (security_invoker = true) AS
 SELECT pc.id,
    pc.store_id,
    pc.count_number,
    pc.status,
    pc.started_at,
    pc.applied_at,
    pc.total_items,
    pc.total_discrepancies,
    pc.total_value_discrepancy,
    s.name AS store_name,
    count(pci.id) AS items_with_count,
    count(pci.id) FILTER (WHERE pci.difference <> 0::numeric) AS items_with_diff,
    sum(pci.value_discrepancy) AS total_value_diff
   FROM physical_counts pc
     JOIN stores s ON s.id = pc.store_id
     LEFT JOIN physical_count_items pci ON pci.count_id = pc.id
  GROUP BY pc.id, s.name;

CREATE VIEW public.v_profiles_unified WITH (security_invoker = true) AS
 SELECT p.id,
    p.email,
    p.full_name,
    p.role_id,
    r.name AS role_name,
    p.role AS role_enum,
    p.active_store_id,
    p.store_id,
    p.is_active,
    p.logo_url,
    p.created_at,
    p.updated_at
   FROM profiles p
     LEFT JOIN roles r ON r.id = p.role_id;

CREATE VIEW public.v_purchase_orders_cxp WITH (security_invoker = true) AS
 SELECT po.id AS po_id,
    po.po_number,
    po.store_id,
    po.supplier_name,
    po.supplier_id,
    po.status AS po_status,
    po.total_amount AS po_total,
    po.created_at AS po_created_at,
    r.id AS receipt_id,
    r.total_cost AS receipt_total,
    r.payment_status,
    r.paid_amount,
    r.due_date,
    r.payment_terms_days,
    r.paid_at,
        CASE
            WHEN r.payment_status = 'paid'::text THEN 'settled'::text
            WHEN r.payment_status = 'partial'::text THEN 'partial'::text
            WHEN r.due_date < CURRENT_DATE AND r.payment_status = 'unpaid'::text THEN 'overdue'::text
            ELSE 'pending'::text
        END AS cxp_status,
    r.total_cost - COALESCE(r.paid_amount, 0::numeric) AS balance_due
   FROM purchase_orders po
     LEFT JOIN receipts r ON r.po_id = po.id
  WHERE (po.status = ANY (ARRAY['partial'::purchase_status_enum, 'received'::purchase_status_enum])) AND r.id IS NOT NULL;

CREATE VIEW public.v_rls_tenant_backfill_audit WITH (security_invoker = true) AS
 SELECT 'products'::text AS table_name,
    count(*) AS null_count
   FROM products
  WHERE products.tenant_id IS NULL
UNION ALL
 SELECT 'transactions'::text AS table_name,
    count(*) AS null_count
   FROM transactions
  WHERE transactions.tenant_id IS NULL
UNION ALL
 SELECT 'stock_movements'::text AS table_name,
    count(*) AS null_count
   FROM stock_movements
  WHERE stock_movements.tenant_id IS NULL
UNION ALL
 SELECT 'inventory'::text AS table_name,
    count(*) AS null_count
   FROM inventory
  WHERE inventory.tenant_id IS NULL
UNION ALL
 SELECT 'profiles'::text AS table_name,
    count(*) AS null_count
   FROM profiles
  WHERE profiles.tenant_id IS NULL
UNION ALL
 SELECT 'commission_payments'::text AS table_name,
    count(*) AS null_count
   FROM commission_payments
  WHERE commission_payments.tenant_id IS NULL
UNION ALL
 SELECT 'commission_rules'::text AS table_name,
    count(*) AS null_count
   FROM commission_rules
  WHERE commission_rules.tenant_id IS NULL
UNION ALL
 SELECT 'receipts'::text AS table_name,
    count(*) AS null_count
   FROM receipts
  WHERE receipts.tenant_id IS NULL
UNION ALL
 SELECT 'workers'::text AS table_name,
    count(*) AS null_count
   FROM workers
  WHERE workers.tenant_id IS NULL
UNION ALL
 SELECT 'sales_transactions'::text AS table_name,
    count(*) AS null_count
   FROM sales_transactions
  WHERE sales_transactions.tenant_id IS NULL
UNION ALL
 SELECT 'production_orders'::text AS table_name,
    count(*) AS null_count
   FROM production_orders
  WHERE production_orders.tenant_id IS NULL
UNION ALL
 SELECT 'audit_events'::text AS table_name,
    count(*) AS null_count
   FROM audit_events
  WHERE audit_events.tenant_id IS NULL
UNION ALL
 SELECT 'price_change_history'::text AS table_name,
    count(*) AS null_count
   FROM price_change_history
  WHERE price_change_history.tenant_id IS NULL;

CREATE VIEW public.v_stock_available WITH (security_invoker = true) AS
 SELECT id AS product_id,
    store_id,
    stock_current,
    stock_current - COALESCE(( SELECT sum(r.quantity) AS sum
           FROM inventory_reservations r
          WHERE r.product_id = p.id AND r.store_id = p.store_id AND r.status = 'ACTIVE'::text), 0::numeric) AS stock_available,
    COALESCE(( SELECT sum(r.quantity) AS sum
           FROM inventory_reservations r
          WHERE r.product_id = p.id AND r.store_id = p.store_id AND r.status = 'ACTIVE'::text), 0::numeric) AS stock_reserved
   FROM products p;

CREATE VIEW public.v_stock_discrepancies WITH (security_invoker = true) AS
 SELECT p.id AS product_id,
    p.name AS product_name,
    p.store_id,
    s.name AS store_name,
    p.stock_current AS current_stock,
    COALESCE(sum(sm.quantity_change), 0::numeric) AS expected_stock,
    p.stock_current - COALESCE(sum(sm.quantity_change), 0::numeric) AS discrepancy
   FROM products p
     LEFT JOIN stock_movements sm ON sm.product_id = p.id AND sm.store_id = p.store_id
     LEFT JOIN stores s ON s.id = p.store_id
  WHERE p.is_active = true AND has_store_access(p.store_id)
  GROUP BY p.id, p.name, p.store_id, s.name, p.stock_current
 HAVING abs(p.stock_current - COALESCE(sum(sm.quantity_change), 0::numeric)) > 0.001;

CREATE MATERIALIZED VIEW public.mv_cash_session AS
 SELECT s.id AS session_id,
    s.store_id,
    s.cashier_id,
    s.opening_cash,
    COALESCE(sum(t.total_amount) FILTER (WHERE t.payment_method = 'cash'::payment_method_enum), 0::numeric) AS cash_sales,
    COALESCE(sum(t.total_amount) FILTER (WHERE t.payment_method = 'card'::payment_method_enum), 0::numeric) AS card_sales,
    COALESCE(sum(m.amount) FILTER (WHERE m.movement_type = 'in'::cash_movement_type_enum AND m.method = 'cash'::payment_method_enum), 0::numeric) AS cash_in,
    COALESCE(sum(m.amount) FILTER (WHERE m.movement_type = 'out'::cash_movement_type_enum AND m.method = 'cash'::payment_method_enum), 0::numeric) AS cash_out
   FROM cash_register_sessions s
     LEFT JOIN transactions t ON t.seller_id = s.cashier_id AND t.created_at >= s.opened_at
     LEFT JOIN cash_movements m ON m.session_id = s.id
  GROUP BY s.id, s.store_id, s.cashier_id, s.opening_cash;

CREATE MATERIALIZED VIEW public.mv_margin_product AS
 SELECT ti.product_id,
    p.name AS product_name,
    sum((ti.price_at_sale - ti.cost_at_sale) * ti.quantity::numeric) AS total_margin,
    sum(ti.quantity) AS total_units
   FROM transaction_items ti
     JOIN products p ON p.id = ti.product_id
  GROUP BY ti.product_id, p.name;

CREATE MATERIALIZED VIEW public.mv_sales_daily AS
 SELECT store_id,
    date_trunc('day'::text, created_at) AS sale_date,
    count(*) AS total_transactions,
    sum(total_amount) AS total_sales,
    sum(subtotal) AS total_subtotal
   FROM transactions
  GROUP BY store_id, (date_trunc('day'::text, created_at));

