CREATE POLICY workers_delete_admin ON public.workers FOR DELETE TO authenticated USING ((EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (p.role = 'admin'::user_role)))));

CREATE POLICY workers_insert_admin_manager ON public.workers FOR INSERT TO authenticated WITH CHECK (((EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (p.role = 'admin'::user_role)))) OR (EXISTS ( SELECT 1
   FROM (user_store_memberships m
     JOIN profiles p ON ((p.id = m.user_id)))
  WHERE ((m.user_id = auth.uid()) AND (m.store_id = workers.store_id) AND (m.status = 'active'::membership_status) AND (p.role = ANY (ARRAY['admin'::user_role, 'manager'::user_role])))))));

CREATE POLICY workers_select_authenticated ON public.workers FOR SELECT TO authenticated USING (((EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (p.role = 'admin'::user_role)))) OR (EXISTS ( SELECT 1
   FROM user_store_memberships m
  WHERE ((m.user_id = auth.uid()) AND (m.store_id = workers.store_id) AND (m.status = 'active'::membership_status))))));

CREATE POLICY workers_service_role_all ON public.workers FOR ALL TO service_role USING (true) WITH CHECK (true);

CREATE POLICY workers_tenant_select ON public.workers FOR SELECT TO authenticated USING (
CASE
    WHEN (current_setting('app.use_tenant_rls'::text, true) = 'true'::text) THEN ((tenant_id = current_user_tenant_id()) AND (is_admin() OR (store_id = ANY (current_user_store_ids()))))
    ELSE (is_admin() OR (store_id = ANY (current_user_store_ids())))
END);

CREATE POLICY workers_update_admin_manager ON public.workers FOR UPDATE TO authenticated USING (((EXISTS ( SELECT 1
   FROM profiles p
  WHERE ((p.id = auth.uid()) AND (p.role = 'admin'::user_role)))) OR (EXISTS ( SELECT 1
   FROM (user_store_memberships m
     JOIN profiles p ON ((p.id = m.user_id)))
  WHERE ((m.user_id = auth.uid()) AND (m.store_id = workers.store_id) AND (m.status = 'active'::membership_status) AND (p.role = ANY (ARRAY['admin'::user_role, 'manager'::user_role])))))));

CREATE POLICY z_reports_select_own ON public.z_reports FOR SELECT TO authenticated USING ((is_admin() OR has_store_role(store_id, ARRAY['admin'::text, 'manager'::text, 'encargado'::text])));

